W=5; n=24; g=8
s=[0,2,4,6,1]
sol=[]
for w in range(W):
    t=w
    row=[]
    # A
    for i in range(8): row.append(i)
    # B
    for j in range(8): row.append((j-t)%8)
    # C
    for k in range(8): row.append((k-s[w])%8)
    sol += row
print(sol)
print(len(sol))
# Verify weeks partitions groups of 3 and pairs no repeat
from collections import Counter, defaultdict
ok=True
for w in range(W):
    row=sol[w*24:(w+1)*24]
    cnt=Counter(row)
    if any(cnt[x]!=3 for x in range(8)) or set(cnt)!=set(range(8)):
        ok=False; print('bad week',w,cnt)
seen={}
repeats=[]
for w in range(W):
    row=sol[w*24:(w+1)*24]
    for gr in range(8):
        members=[p for p in range(24) if row[p]==gr]
        for a in range(3):
            for b in range(a+1,3):
                pair=tuple(sorted((members[a],members[b])))
                if pair in seen:
                    repeats.append((pair,seen[pair],w))
                seen[pair]=w
print('ok', ok, 'repeats', len(repeats), 'pairs', len(seen))
if repeats[:5]: print(repeats[:5])
# print groups for clarity
for w in range(W):
    print('week',w)
